"""Eywa model types, parameters and the typed expression AST.

The module provides:

* the type lattice (``Void``, ``Bool``, ``Char``, ``Int``, ``String``,
  ``Enum``, ``Array``, ``Struct``, ``Alias``) plus declaration resolution,
* the typed expression AST with a JSON-expression compiler, and
* an evaluator implementing the documented predicate semantics (deep
  equality, exact modular unsigned arithmetic, lexical ``all`` bindings and
  short-circuiting Boolean connectives).
"""

from ast import NodeVisitor
from typing import Any, Dict, List, Union

from . import regex as re


class ExpressionError(Exception):
    """Raised when an expression cannot be compiled against a scope."""


class Type(object):
    """An Eywa type for a parameter or a result."""

    @staticmethod
    def inner(type):
        """Look past any type aliases to get the inner type."""
        while isinstance(type, Alias):
            type = type.type
        return type


class Void(Type):
    """A void type representing no value."""


class Bool(Type):
    """A boolean type representing true or false."""


class Char(Type):
    """A character type representing a single Latin-1 character."""


def int_width(bits):
    """Smallest number of bytes (1, 2, 4, 8) that holds ``bits`` bits."""
    if bits <= 8:
        return 1
    if bits <= 16:
        return 2
    if bits <= 32:
        return 4
    return 8


class Int(Type):
    """An unsigned integer type of a given width in bits."""

    def __init__(self, bits=32):
        self.bits = int(bits)
        self.size = self.bits

    @property
    def width(self):
        return int_width(self.bits)

    @property
    def modulus(self):
        return 1 << self.bits


class String(Type):
    """A bounded Latin-1 C string type."""

    def __init__(self, maxsize=6):
        if maxsize < 0:
            raise ExpressionError('invalid string type')
        self.maxsize = int(maxsize)
        self.char_type = Char()


class Enum(Type):
    """An enumeration type with named values."""

    def __init__(self, name, values):
        self.name = name
        self.values = list(values)


class Array(Type):
    """A fixed-length array type."""

    def __init__(self, element_type, maxsize):
        self.element_type = element_type
        self.size = int(maxsize)
        self.maxsize = self.size


class Struct(Type):
    """A struct type with ordered fields."""

    def __init__(self, name, fields=None):
        self.name = name
        self.fields = {} if fields is None else dict(fields)


class Alias(Type):
    """A transparent value/layout alias that keeps its declaration name."""

    def __init__(self, name, type, description=None):
        self.name = name
        self.type = type
        self.description = description


def build_types(declarations):
    """Resolve a list of named type declarations into a name -> Type map."""
    raw = {}
    for declaration in declarations:
        name = declaration['name']
        if name in raw:
            raise ExpressionError('duplicate type declaration ' + str(name))
        raw[name] = declaration
    cache = {}
    building = set()

    def resolve(name):
        if name in cache:
            return cache[name]
        if name not in raw:
            raise ExpressionError('unknown type ' + str(name))
        if name in building:
            raise ExpressionError('cyclic type ' + str(name))
        building.add(name)
        declaration = raw[name]
        kind = declaration['kind']
        if kind == 'bool':
            resolved = Bool()
        elif kind == 'char':
            resolved = Char()
        elif kind == 'void':
            resolved = Void()
        elif kind == 'int':
            resolved = Int(declaration['bits'])
        elif kind == 'string':
            resolved = String(declaration['maxsize'])
        elif kind == 'enum':
            resolved = Enum(name, declaration['values'])
        elif kind == 'array':
            resolved = Array(resolve(declaration['element']), declaration['size'])
        elif kind == 'struct':
            resolved = Struct(name, [(field, resolve(kind_name))
                                     for field, kind_name in declaration['fields']])
        elif kind == 'alias':
            resolved = Alias(name, resolve(declaration['target']),
                             declaration.get('description'))
        else:
            raise ExpressionError('unknown type kind ' + str(kind))
        building.discard(name)
        cache[name] = resolved
        return resolved

    for name in raw:
        resolve(name)
    return cache


def values_equal(left, right):
    """Deep value equality for Eywa values of the same underlying type."""
    if isinstance(left, bool) != isinstance(right, bool):
        return False
    if isinstance(left, dict):
        if not isinstance(right, dict) or len(left) != len(right):
            return False
        for key, item in left.items():
            if key not in right or not values_equal(item, right[key]):
                return False
        return True
    if isinstance(left, (list, tuple)):
        if isinstance(right, (list, tuple)):
            if len(left) != len(right):
                return False
            return all(values_equal(a, b) for a, b in zip(left, right))
        return False
    if isinstance(right, (dict, list, tuple)):
        return False
    return left == right


class Expr(object):
    """A simple expression class."""

    @staticmethod
    def eval(expr, assignment):
        """Evaluate an Eywa expression given an assignment of variables."""
        return Evaluator(assignment).visit(expr)

    @staticmethod
    def convert(other):
        """Ensures that the given object can be converted to an expression."""
        if isinstance(other, Expr):
            return other
        if isinstance(other, int) and not isinstance(other, bool):
            return Const(Int(32), other)
        if isinstance(other, Parameter):
            return Var(Type.inner(other.type), other.name)
        raise ExpressionError('invalid expression: ' + str(other))

    @staticmethod
    def has_match(type):
        """Determines if this expression has a match expression."""
        return HasMatch().visit(type)

    def get_field(self, field):
        """A helper function to create a field dereference."""
        return Field(Type.inner(self.type.fields[field]), self, field)

    def __invert__(self):
        return Not(Bool(), self)

    def matches(self, regex):
        """A helper function to create a match constraint."""
        return Match(Bool(), self, regex)

    def forall(self, invariant):
        """A helper function to create an array forall expression."""
        return Forall(Bool(), self, invariant)

    def implies(self, other):
        """A helper function to create an implies expression."""
        return Binop(Bool(), 'implies', self, Expr.convert(other))


class Var(Expr):
    """A variable expression referring to an input or an ``all`` binding."""

    def __init__(self, type, parameter_name):
        self.type = type
        self.name = parameter_name
        self.parameter_name = parameter_name


class Const(Expr):
    """A typed constant expression."""

    def __init__(self, type, constant):
        self.type = type
        self.constant = constant


class Not(Expr):
    """A Boolean complement expression."""

    def __init__(self, type, expr):
        self.type = type
        self.expr = expr


class Match(Expr):
    """A full byte-string regular-language membership expression."""

    def __init__(self, type, expr, regex):
        self.type = type
        self.expr = expr
        self.regex = regex

    def test(self, value):
        return re.ismatch(self.regex, value)


class Binop(Expr):
    """A binary operation expression."""

    def __init__(self, type, op, left, right):
        self.type = type
        self.op = op
        self.left = left
        self.right = right


class Field(Expr):
    """A struct field dereference expression."""

    def __init__(self, type, expr, field):
        self.type = type
        self.expr = expr
        self.field = field


class Index(Expr):
    """A statically valid array indexing expression."""

    def __init__(self, type, expr, index):
        self.type = type
        self.expr = expr
        self.index = index


class All(Expr):
    """An array forall expression binding each element lexically."""

    def __init__(self, type, binding, array_expr, body):
        self.type = type
        self.binding = binding
        self.array_expr = array_expr
        self.body = body


#: Historic name for :class:`All`, kept for compatibility.
Forall = All


_MISSING = object()


class Evaluator(NodeVisitor):
    """Evaluates an Eywa expression and returns a value."""

    def __init__(self, assignment):
        self.assignment = assignment

    def visit_Var(self, node):
        try:
            return self.assignment[node.name]
        except KeyError:
            raise ExpressionError('unbound variable ' + str(node.name))

    def visit_Const(self, node):
        return node.constant

    def visit_Not(self, node):
        return not self.visit(node.expr)

    def visit_Match(self, node):
        return node.test(self.visit(node.expr))

    def visit_Field(self, node):
        return self.visit(node.expr)[node.field]

    def visit_Index(self, node):
        return self.visit(node.expr)[node.index]

    def visit_All(self, node):
        array = self.visit(node.array_expr)
        assignment = self.assignment
        binding = node.binding
        previous = assignment.get(binding, _MISSING)
        body = node.body
        try:
            for element in array:
                assignment[binding] = element
                if not self.visit(body):
                    return False
        finally:
            if previous is _MISSING:
                assignment.pop(binding, None)
            else:
                assignment[binding] = previous
        return True

    def visit_Binop(self, node):
        op = node.op
        if op == 'and':
            if not self.visit(node.left):
                return False
            return bool(self.visit(node.right))
        if op == 'or':
            if self.visit(node.left):
                return True
            return bool(self.visit(node.right))
        if op == 'implies':
            if not self.visit(node.left):
                return True
            return bool(self.visit(node.right))
        left = self.visit(node.left)
        right = self.visit(node.right)
        if op == 'eq':
            return values_equal(left, right)
        if op == 'ne':
            return not values_equal(left, right)
        if op == 'lt':
            return left < right
        if op == 'le':
            return left <= right
        if op == 'gt':
            return left > right
        if op == 'ge':
            return left >= right
        if op == 'add' or op == 'sub':
            modulus = node.type.modulus
            if op == 'add':
                return (left + right) % modulus
            return (left - right) % modulus
        raise ExpressionError('unknown binary operator: ' + str(op))


#: Symbol spellings accepted by :func:`compile_expression` in addition to the
#: documented operator names.
_OPERATOR_ALIASES = {
    '==': 'eq', '!=': 'ne', '<': 'lt', '<=': 'le', '>': 'gt', '>=': 'ge',
    '+': 'add', '-': 'sub', '&': 'and', '|': 'or',
}

_RELATIONS = frozenset(('eq', 'ne', 'lt', 'le', 'gt', 'ge'))
_ARITHMETIC = frozenset(('add', 'sub'))
_CONNECTIVES = frozenset(('and', 'or', 'implies'))


def static_value(expr):
    """Return the value of a purely constant expression, else ``None``."""
    if isinstance(expr, Const):
        return expr.constant
    if isinstance(expr, Binop) and expr.type is not None and \
            isinstance(expr.type, Int) and expr.op in _ARITHMETIC:
        left = static_value(expr.left)
        right = static_value(expr.right)
        if left is None or right is None:
            return None
        modulus = expr.type.modulus
        return ((left + right) if expr.op == 'add' else (left - right)) % modulus
    return None


def compile_expression(node, scope, types, patterns=None):
    """Compile a JSON expression array against a lexical scope of types.

    ``scope`` maps visible variable names to their (alias-resolved) types;
    ``types`` maps declared type names to type objects.
    """
    if patterns is None:
        patterns = {}
    return _compile(node, scope, types, patterns)


def _compile(node, scope, types, patterns):
    if not isinstance(node, list) or not node:
        raise ExpressionError('expression must be a non-empty array')
    head = node[0]
    if head == 'var':
        if len(node) != 2:
            raise ExpressionError('var takes one name')
        name = node[1]
        if name not in scope:
            raise ExpressionError('unbound variable ' + str(name))
        return Var(scope[name], name)
    if head == 'const':
        if len(node) != 3:
            raise ExpressionError('const takes a type and a value')
        type_name, value = node[1], node[2]
        if type_name not in types:
            raise ExpressionError('unknown type ' + str(type_name))
        return Const(Type.inner(types[type_name]), value)
    if head == 'field':
        if len(node) != 3:
            raise ExpressionError('field takes a value and a field name')
        base = _compile(node[1], scope, types, patterns)
        struct = base.type
        if not isinstance(struct, Struct):
            raise ExpressionError('field expression expected struct type')
        if node[2] not in struct.fields:
            raise ExpressionError('unknown field ' + str(node[2]))
        return Field(Type.inner(struct.fields[node[2]]), base, node[2])
    if head == 'index':
        if len(node) != 3:
            raise ExpressionError('index takes an array and an index')
        array = _compile(node[1], scope, types, patterns)
        array_type = array.type
        if not isinstance(array_type, Array):
            raise ExpressionError('index expression expected array type')
        index = node[2]
        if isinstance(index, list):
            index = static_value(_compile(index, scope, types, patterns))
        if not isinstance(index, int) or isinstance(index, bool):
            raise ExpressionError('index must be a constant integer')
        if index < 0 or index >= array_type.size:
            raise ExpressionError('index out of bounds')
        return Index(Type.inner(array_type.element_type), array, index)
    if head == 'all':
        if len(node) != 4:
            raise ExpressionError('all takes a binding, an array and a body')
        binding, array_node, body_node = node[1], node[2], node[3]
        array = _compile(array_node, scope, types, patterns)
        array_type = array.type
        if not isinstance(array_type, Array):
            raise ExpressionError('all expression expected array type')
        inner_scope = dict(scope)
        inner_scope[binding] = Type.inner(array_type.element_type)
        body = _compile(body_node, inner_scope, types, patterns)
        return All(Bool(), binding, array, body)
    if head == 'match':
        if len(node) != 3:
            raise ExpressionError('match takes a string and a pattern')
        target = _compile(node[1], scope, types, patterns)
        if not isinstance(target.type, String):
            raise ExpressionError('match expression expected string type')
        pattern = node[2]
        if not isinstance(pattern, str):
            raise ExpressionError('pattern must be a string')
        regex = patterns.get(pattern)
        if regex is None:
            regex = re.parse(pattern)
            patterns[pattern] = regex
        return Match(Bool(), target, regex)
    if head == 'not':
        if len(node) != 2:
            raise ExpressionError('not takes one predicate')
        return Not(Bool(), _compile(node[1], scope, types, patterns))
    op = _OPERATOR_ALIASES.get(head, head)
    if op in _RELATIONS or op in _ARITHMETIC or op in _CONNECTIVES:
        if len(node) != 3:
            raise ExpressionError('binary operation takes two operands')
        left = _compile(node[1], scope, types, patterns)
        right = _compile(node[2], scope, types, patterns)
        left_type = left.type
        right_type = right.type
        if op in _CONNECTIVES:
            if not isinstance(left_type, Bool) or not isinstance(right_type, Bool):
                raise ExpressionError('connective expected Boolean operands')
            return Binop(Bool(), op, left, right)
        if not isinstance(left_type, Int) or not isinstance(right_type, Int):
            raise ExpressionError('operation expected integer operands')
        if op in _ARITHMETIC:
            if left_type.bits != right_type.bits:
                raise ExpressionError('arithmetic needs matching integer types')
            return Binop(Int(left_type.bits), op, left, right)
        return Binop(Bool(), op, left, right)
    raise ExpressionError('unknown expression form ' + str(head))


class HasMatch(NodeVisitor):
    """Checks if an Eywa expression contains a match expression."""

    def visit_Var(self, node):
        return False

    def visit_Const(self, node):
        return False

    def visit_Match(self, node):
        return True

    def visit_Not(self, node):
        return self.visit(node.expr)

    def visit_Field(self, node):
        return self.visit(node.expr)

    def visit_Index(self, node):
        return self.visit(node.expr)

    def visit_All(self, node):
        return self.visit(node.array_expr) or self.visit(node.body)

    def visit_Binop(self, node):
        return self.visit(node.left) or self.visit(node.right)


class Parameter(object):
    """An Eywa parameter to a function."""

    def __init__(self, name, type, description=None):
        self.name = name
        self.type = type
        self.description = description


class Function(object):
    """An Eywa function that represents a model."""

    def __init__(self, name, description, inputs, precondition=None):
        unique_names = set(item.name for item in inputs)
        if len(unique_names) != len(inputs):
            raise ExpressionError('duplicate parameter names')
        self.name = name
        self.description = description
        self.inputs = inputs[:-1]
        self.result = inputs[-1]
        self.precondition = precondition


class FuncModule(Function):
    """An Eywa function module used for composition."""

    def __init__(self, name, description, inputs):
        Function.__init__(self, name, description, inputs)
